{
"title": "Poller health",
"timeRange": {"from": "now-1h", "to": "now"},
"refreshIntervalMs": 15000,
"variables": [
{
"name": "dashboard",
"type": "query",
"label": "Dashboard",
"query": {"sourceId": "eval-prometheus-demo", "label": "dashboard", "match": "holotable_poller_tick_duration_seconds_count"}
}
],
"panels": [
{
"id": "p95-tick",
"title": "Poller tick p95 duration",
"viz": "line",
"description": "95th percentile of one poller cycle's duration, in milliseconds, for the selected dashboard, computed from the tick-duration histogram over 5-minute rates.",
"format": "ms",
"query": {
"sourceId": "eval-prometheus-demo",
"promql": "histogram_quantile(0.95, sum by (le) (rate(holotable_poller_tick_duration_seconds_bucket{dashboard=\":dashboard\"}[5m]))) * 1000"
},
"options": {"decimals": 1, "yAxis": {"label": "ms", "min": 0}},
"layout": {"x": 0, "y": 0, "w": 6, "h": 4}
},
{
"id": "open-streams",
"title": "Open streams",
"viz": "line",
"description": "Number of open dashboard streams (SSE subscribers) for the selected dashboard, summed across instances and jobs.",
"format": "number",
"query": {
"sourceId": "eval-prometheus-demo",
"promql": "sum(holotable_sse_subscribers{dashboard=\":dashboard\"})"
},
"options": {"decimals": 0, "yAxis": {"min": 0}},
"layout": {"x": 6, "y": 0, "w": 6, "h": 4}
}
]
}
